function New-HubSetting {
 param($Section,$Key,$Label,$Group,$Type='choice',$Values=@('auto','true','false'),$Minimum=$null,$Maximum=$null,$Description='',$ValueLabels=@{},$MissingValue='auto')
 if($null -ne $Minimum){$Minimum=[double]$Minimum};if($null -ne $Maximum){$Maximum=[double]$Maximum}
 $localized=$script:HubSettingLanguageMetadata[$Section+'/'+$Key]
 # Optional metadata is absent for some generated/settings-only rows. Keep the
 # JSON schema stable and preserve the existing prose fallback.
 $valueLabelIds=@{};if($null -ne $localized.valueLabelIds){$valueLabelIds=$localized.valueLabelIds}
 [pscustomobject]@{section=$Section;key=$Key;labelId=[string]$localized.labelId;descriptionId=[string]$localized.descriptionId;valueLabelIds=$valueLabelIds;label=$Label;group=$Group;type=$Type;values=@($Values);minimum=$Minimum;maximum=$Maximum;description=$Description;valueLabels=$ValueLabels;missingValue=$MissingValue}
}
