# The additional-pass profile keys and ranges are shared by the actual Config
# layer loader and DlssNr_Menu.cpp's Pass 2..10 controls. Missing values stay auto
# so Config can retain its predecessor-inheritance behavior on the next launch.
$layerKeys=@('WorkingScale','ScalingDownscaler','Preset','Style','Transfer','Intensity','TransferStrength','ColourStrength','MaxRatio','LocalStructure','LocalTone','SkinStructure','AutoMask','ReversibleMode','ApplyModel')
foreach($pass in 2..10){
 foreach($key in $layerKeys){
  $base=@($script:HubSettingsSchema|Where-Object{$_.section -ceq 'DlssNr' -and $_.key -ceq $key})[0]
  $values=$base.values;$labels=$base.valueLabels
  if($key -eq 'ReversibleMode'){$values=@('auto','0','1','2');$labels=@{'0'='Soft-knee composition';'1'='Neutwo composition';'2'='Neutwo pure inverse'}}
  $script:HubSettingsSchema+=New-HubSetting ('DlssNrLayer'+$pass) $key $base.label $nr -Type $base.type -Values $values -Minimum $base.minimum -Maximum $base.maximum -ValueLabels $labels -Description ('Pass '+$pass+'. Automatic retains the in-game loader''s preceding-pass inheritance. Applies only when Advanced Multipass includes this pass.')
 }
}
