function Read-HubSettingsDocument([string]$Path){
 $bytes=[IO.File]::ReadAllBytes($Path);$offset=0
 if($bytes.Length -ge 4 -and [BitConverter]::ToUInt32($bytes,0) -eq 65279){$encoding=New-Object Text.UTF32Encoding($false,$true,$true);$offset=4}
 elseif($bytes.Length -ge 4 -and $bytes[0] -eq 0 -and $bytes[1] -eq 0 -and $bytes[2] -eq 254 -and $bytes[3] -eq 255){$encoding=New-Object Text.UTF32Encoding($true,$true,$true);$offset=4}
 elseif($bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191){$encoding=New-Object Text.UTF8Encoding($true,$true);$offset=3}
 elseif($bytes.Length -ge 2 -and $bytes[0] -eq 255 -and $bytes[1] -eq 254){$encoding=New-Object Text.UnicodeEncoding($false,$true,$true);$offset=2}
 elseif($bytes.Length -ge 2 -and $bytes[0] -eq 254 -and $bytes[1] -eq 255){$encoding=New-Object Text.UnicodeEncoding($true,$true,$true);$offset=2}
 else{try{$encoding=New-Object Text.UTF8Encoding($false,$true);[void]$encoding.GetString($bytes)}catch{$encoding=[Text.Encoding]::GetEncoding(1252)}}
 $text=$encoding.GetString($bytes,$offset,$bytes.Length-$offset)
 $bom=New-Object byte[] $offset;if($offset){[Array]::Copy($bytes,0,$bom,0,$offset)}
 $entries=New-Object Collections.Generic.List[object];$sections=New-Object Collections.Generic.List[object];$section=''
 foreach($line in [regex]::Matches($text,'([^\r\n]*)(\r\n|\n|\r|$)')){
  if($line.Value.Length -eq 0){continue}
  $content=$line.Groups[1].Value
  if($content -match '^\s*\[([^\]]+)\]'){$section=$matches[1].Trim();if($sections.Count){$sections[$sections.Count-1].endIndex=$line.Index};$sections.Add([pscustomobject]@{name=$section;index=$line.Index;endIndex=$text.Length});continue}
  if($content -match '^\s*([^;#=\s][^=]*?)\s*=\s*([^;#\r\n]*?)(\s*(?:[;#].*)?)$'){
   $key=$matches[1].Trim();$value=$matches[2].Trim()
   $match=[regex]::Match($content,'^(\s*[^;#=\s][^=]*?\s*=\s*)([^;#\r\n]*?)(\s*(?:[;#].*)?)$')
   $entries.Add([pscustomobject]@{section=$section;key=$key;value=$value;index=($line.Index+$match.Groups[2].Index);length=$match.Groups[2].Length})
  }
 }
 return [pscustomobject]@{bytes=$bytes;encoding=$encoding;bom=$bom;text=$text;entries=$entries.ToArray();sections=$sections.ToArray()}
}
function Get-HubSettingsProjection([string]$Root){
 $path=SafePath $Root 'OptiScaler.ini';if(-not (Test-Path -LiteralPath $path)){return @()}
 return @(ConvertTo-HubSettingsProjection (Read-HubSettingsDocument $path))
}
function ConvertTo-HubSettingsProjection($doc){
 return @($script:HubSettingsSchema|ForEach-Object{
  $schema=$_;$entry=@($doc.entries|Where-Object{$_.section -ieq $schema.section -and $_.key -ieq $schema.key})
  $sections=@($doc.sections|Where-Object{$_.name -ieq $schema.section})
  $missingValue=$schema.missingValue
  if($schema.section -eq 'DlssNr' -and $schema.key -eq 'PresentInputPolicy' -and $entry.Count -eq 0){
   $route=@($doc.entries|Where-Object{$_.section -ieq 'DlssNr' -and $_.key -ieq 'Route'})
   if($route.Count -eq 1){if($route[0].value -eq '1'){$missingValue='0'}elseif($route[0].value -eq '2'){$missingValue='1'}}
  }
  [pscustomobject]@{section=$schema.section;key=$schema.key;labelId=$schema.labelId;descriptionId=$schema.descriptionId;valueLabelIds=$schema.valueLabelIds;label=$schema.label;group=$schema.group;type=$schema.type;values=$schema.values;minimum=$schema.minimum;maximum=$schema.maximum;description=$schema.description;valueLabels=$schema.valueLabels;value=$(if($entry.Count -eq 1){$entry[0].value}else{$missingValue});available=($entry.Count -le 1 -and $sections.Count -le 1);present=($entry.Count -eq 1)}
 })
}
function Get-HubDefaultSettings($Target,$Inspection,$Package){
 # Fresh installation defaults come from the same approved payload as Setup,
 # never the current INI, retained user settings or an inspection cache.
 $defaultPath='payload\OptiScaler.ini'
 $entries=@($Package.manifest.files|Where-Object{$_.path.Replace('/','\') -ieq $defaultPath})
 if($entries.Count -ne 1){throw 'Approved package has no unique default INI'}
 $path=SafePath $Package.root $entries[0].path
 $document=Read-HubSettingsDocument $path
 if((HashBytes $document.bytes) -ine $entries[0].sha256){throw 'Approved default INI changed'}
 $defaults=@(ConvertTo-HubSettingsProjection $document)
 # Explicit coexistence is carried by the small receipt. Missing or edited
 # game files never require a restore-chain health check.
 $loadReShade=[bool](Get-HubProperty $Inspection.state 'reshadeRename')
 $result=New-Object Collections.Generic.List[object]
 foreach($default in $defaults){
  $current=@($Inspection.settings|Where-Object{$_.section -ceq $default.section -and $_.key -ceq $default.key})
  if($current.Count -ne 1 -or -not $current[0].available){continue}
  if(-not $default.available){throw ('Ambiguous package default: '+$default.section+'/'+$default.key)}
  $value=[string]$default.value
  if($loadReShade -and $default.section -eq 'Plugins' -and $default.key -eq 'LoadReShade'){$value='true'}
  $schema=@($script:HubSettingsSchema|Where-Object{$_.section -ceq $default.section -and $_.key -ceq $default.key})
  if($schema.Count -ne 1 -or -not (Test-HubSettingValue $schema[0] $value)){throw ('Unsupported package default: '+$default.section+'/'+$default.key)}
  # Automatic is intentional: dllmain's getQuirksForExe re-resolves game and
  # GPU facts at next launch (including dd2.exe); do not freeze runtime facts.
  if($current[0].value -cne $value){$result.Add([pscustomobject]@{section=$default.section;key=$default.key;value=$value})}
 }
 # Run the exact Save Settings coupled-value and ambiguity checks read-only.
 [void](Get-HubSettingsBytes (Get-HubSettingsRoot $Target) $result.ToArray())
 return $result.ToArray()
}
function Test-HubSettingValue($Schema,[string]$Value){
 if($Schema.type -eq 'objectrules'){
  if($Value -ceq 'auto'){return $true}
  if($Value.Length -gt 4194304 -or $Value.Length % 2 -ne 0 -or $Value -cnotmatch '^[0-9a-f]+$'){return $false}
  try {
   $bytes=New-Object byte[] ($Value.Length/2)
   for($i=0;$i -lt $bytes.Length;$i++){$bytes[$i]=[Convert]::ToByte($Value.Substring($i*2,2),16)}
   $encoding=New-Object Text.UTF8Encoding($false,$true);$text=$encoding.GetString($bytes)
   if(-not ('NeuRoticHubJson' -as [type])){Add-Type -Path (Join-Path $PSScriptRoot 'NeuRotic-HubJson.cs')}
   [NeuRoticHubJson]::Validate($text)
   $profile=$text | ConvertFrom-Json
   return Test-ObjectRuleProfile $profile
  }catch{return $false}
 }

 if($Schema.values.Count){return $Value -cin $Schema.values}
 if($Value -ceq 'auto'){return $true}
 $number=0.0
 if($Schema.type -eq 'keycode' -and $Value -match '^0[xX][0-9a-fA-F]{1,3}$'){$number=[Convert]::ToInt32($Value.Substring(2),16)}
 elseif($Schema.type -in @('integer','keycode')){
  if($Value -notmatch '^-?[0-9]+$' -or -not [double]::TryParse($Value,[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$number)){return $false}
 }elseif(-not [double]::TryParse($Value,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$number)){return $false}
 if($Schema.type -eq 'keycode' -and $number -gt 255){
  if($number -gt 2047){return $false};$vk=[int]$number -band 255
  # Modifier combinations require an ordinary keyboard key, never a modifier,
  # mouse button, Windows key, or an empty/undefined base code.
  $ordinary=$vk -in @(8,9,13,19,20,27,44,45,46,93,144,145,226) -or ($vk -ge 32 -and $vk -le 40) -or ($vk -ge 48 -and $vk -le 57) -or ($vk -ge 65 -and $vk -le 90) -or ($vk -ge 96 -and $vk -le 135) -or ($vk -ge 166 -and $vk -le 183) -or ($vk -ge 186 -and $vk -le 192) -or ($vk -ge 219 -and $vk -le 223)
  if(-not $ordinary){return $false}
 }
 return -not [double]::IsNaN($number) -and -not [double]::IsInfinity($number) -and $number -ge $Schema.minimum -and $number -le $Schema.maximum
}
function Get-HubSettingsBytes([string]$Root,$Patches){
 $doc=Read-HubSettingsDocument (SafePath $Root 'OptiScaler.ini')
 if(@($Patches).Count -gt 512){throw 'Too many settings edits'}
 $edits=New-Object Collections.Generic.List[object];$seen=@{};$missing=[ordered]@{}
 foreach($patch in @($Patches)){
  foreach($name in $patch.PSObject.Properties.Name){if($name -cnotin @('section','key','value')){throw 'Unknown settings patch field'}}
  $id=$patch.section+'/'+$patch.key;if($seen.ContainsKey($id)){throw 'Duplicate settings edit'};$seen[$id]=$patch.value
  $schema=@($script:HubSettingsSchema|Where-Object{$_.section -ceq $patch.section -and $_.key -ceq $patch.key})
  if($schema.Count -ne 1 -or $patch.value -isnot [string] -or ($patch.value.Length -gt 64 -and $schema[0].type -ne 'objectrules')){throw 'Setting is not in the current editable schema'}
  if(-not (Test-HubSettingValue $schema[0] $patch.value)){throw ('Unsupported value for '+$id)}
  $entries=@($doc.entries|Where-Object{$_.section -ieq $patch.section -and $_.key -ieq $patch.key})
  $sections=@($doc.sections|Where-Object{$_.name -ieq $patch.section})
  if($entries.Count -gt 1 -or $sections.Count -gt 1){throw 'Setting or section ambiguous in this game INI; preserved'}
  if($entries.Count -eq 1){$edits.Add([pscustomobject]@{index=$entries[0].index;length=$entries[0].length;value=$patch.value;insertion=$false})}
  else{
   if(-not $missing.Contains($patch.section)){$missing[$patch.section]=New-Object Collections.Generic.List[object]}
   $missing[$patch.section].Add($patch)
  }
 }
 # Validate coupled values against the complete proposed draft, not edit order.
 $effective={param($section,$key,$fallback)
  $id=$section+'/'+$key;if($seen.ContainsKey($id)){return $seen[$id]}
  $entry=@($doc.entries|Where-Object{$_.section -ieq $section -and $_.key -ieq $key})
  if($entry.Count -eq 1){return $entry[0].value};return $fallback
 }
 # Validate only the requested coupled settings; unrelated legacy values stay intact.
 $ratioKeys=@('UpscaleRatio/UpscaleRatioOverrideValue','QualityOverrides/QualityRatioDLAA','QualityOverrides/QualityRatioUltraQuality','QualityOverrides/QualityRatioQuality','QualityOverrides/QualityRatioBalanced','QualityOverrides/QualityRatioPerformance','QualityOverrides/QualityRatioUltraPerformance')
 $extended=(& $effective Menu ExtendedLimits 'false') -ieq 'true'
 foreach($id in $ratioKeys){
  if($seen.ContainsKey($id)){
   $value=$seen[$id];if($value -ceq 'auto'){continue}
   $number=[double]::Parse($value,[Globalization.CultureInfo]::InvariantCulture)
   if(-not $extended -and ($number -lt 1 -or $number -gt 3)){throw 'Ratio values outside 1–3 require Enable Extended Limits in the same saved draft'}
  }
 }
 if($seen.ContainsKey('CAS/DADepthBias') -and $seen['CAS/DADepthBias'] -cne 'auto'){
  $bias=[double]::Parse($seen['CAS/DADepthBias'],[Globalization.CultureInfo]::InvariantCulture)
  if($bias -gt .003 -and $bias -lt .005){throw 'Depth Bias must be 0.0001–0.003 for non-linear depth or 0.005–0.03 for linear depth'}
 }
 if(@($seen.Keys|Where-Object{$_ -like 'OutputScaling/*' -or $_ -ceq 'InitFlags/DisplayResolution'}).Count){
  if((& $effective OutputScaling Enabled 'false') -ieq 'true' -and (& $effective InitFlags DisplayResolution 'auto') -ieq 'true'){throw 'Output scaling and Display Res. MV cannot both be explicitly enabled; disable one in this draft'}
 }
 foreach($prefix in @('Present','Enhanced')){
  $modeKey=$prefix+'Resolution';$scaleKey=$prefix+'CustomScale'
  if($seen.ContainsKey('DlssNr/'+$modeKey) -or $seen.ContainsKey('DlssNr/'+$scaleKey)){
   $mode=& $effective DlssNr $modeKey 'auto';$scale=& $effective DlssNr $scaleKey 'auto'
   if($scale -ne 'auto'){
    $number=0;if(-not [int]::TryParse($scale,[ref]$number)){throw 'Custom resolution scale must be a whole number'}
    if(($mode -in @('3','4') -and ($number -lt 25 -or $number -gt 200)) -or ($mode -notin @('3','4') -and ($number -lt 0 -or $number -gt 5))){throw 'Custom resolution scale does not match its resolution mode'}
   }
  }
 }
 if(@($seen.Keys|Where-Object{$_ -like 'DlssNrBasic/*'}).Count){
  $maximum=& $effective DlssNrBasic MaximumPasses '1';if($maximum -eq 'auto'){$maximum='1'}
  foreach($key in @('ModelStrength','DetailStrength')){
   $value=& $effective DlssNrBasic $key '1';if($value -eq 'auto'){$value='1'}
   $strength=0.0;$limit=0.0
   if(-not [double]::TryParse($value,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$strength) -or -not [double]::TryParse($maximum,[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$limit) -or $strength -gt $limit){throw 'Basic strength exceeds the selected maximum pass count'}
  }
 }
 $newline=[regex]::Match($doc.text,'\r\n|\n|\r').Value;if(-not $newline){$newline="`r`n"}
 $insertions=@{}
 # Existing sections first, followed by wholly new sections at EOF. This keeps
 # a last-section key from accidentally landing in a newly appended section.
 foreach($existing in @($true,$false)){
  foreach($section in $missing.Keys){
   $matches=@($doc.sections|Where-Object{$_.name -ieq $section});if(($matches.Count -eq 1) -ne $existing){continue}
   $index=$doc.text.Length;if($existing){$index=$matches[0].endIndex}
   $block='';if(-not $existing){$block='['+$section+']'+$newline}
   foreach($patch in $missing[$section]){$block+=$patch.key+'='+$patch.value+$newline}
   if(-not $insertions.ContainsKey($index)){
    $insertions[$index]='';if($index -gt 0 -and $doc.text[$index-1] -notin @([char]10,[char]13)){$insertions[$index]=$newline}
   }
   $insertions[$index]+=$block
  }
 }
 foreach($index in $insertions.Keys){$edits.Add([pscustomobject]@{index=[int]$index;length=0;value=$insertions[$index];insertion=$true})}
 $text=$doc.text;foreach($edit in @($edits|Sort-Object @{Expression="index";Descending=$true},@{Expression="insertion";Descending=$true})){$text=$text.Remove($edit.index,$edit.length).Insert($edit.index,$edit.value)}
 $body=$doc.encoding.GetBytes($text);$result=New-Object byte[] ($doc.bom.Length+$body.Length)
 [Array]::Copy($doc.bom,0,$result,0,$doc.bom.Length);[Array]::Copy($body,0,$result,$doc.bom.Length,$body.Length)
 return ,$result
}
function Get-HubSettingsRelativePath($Target){
 return 'OptiScaler.ini'
}
function Get-HubSettingsRoot($Target){
 $relative=Get-HubSettingsRelativePath $Target
 if($relative -eq 'OptiScaler.ini'){return $Target.directory}
 return Split-Path -Parent (SafePath $Target.directory $relative)
}
function Test-HubPreparedSetting([string]$Section,[string]$Key){
 if($Section -ceq 'DlssNrBasic'){return $true}
 if($Section -ceq 'DlssNr'){
  return $Key -cnotin @('ToggleKey','VulkanPrepare','Route','RenderingMode','PresentResolution','PresentCustomScale','ExperimentalMode','PreSrSoftReset','PreparedDepth')
 }
 return $false
}
function Invoke-HubSettingsSave($Target,$Request){
 $relative=Get-HubSettingsRelativePath $Target
 $path=SafePath $Target.directory $relative
 if((HashFile $path) -ne $Request.configRevision){return [ordered]@{status='PreconditionChanged';reason='Settings changed externally; reload'}}
 if($Target.bitness -ne 64){throw 'In-game settings are unavailable for this architecture. Use NR Anything.'}
 $new=Get-HubSettingsBytes (Get-HubSettingsRoot $Target) $Request.settings
 $written=WriteVerifiedBytes $new $path (HashBytes $new) $Request.configRevision
 if(-not $written){return [ordered]@{status='PreconditionChanged';reason='Settings changed externally; outside edit preserved. Reload before saving.'}}
 return [ordered]@{status='Succeeded';configRevision=(HashFile $path)}
}
